SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(l),'owner',pg_get_userbyid(l.lanowner),'call_handler',CASE WHEN l.lanplcallfoid<>0 THEN to_jsonb(pg_identify_object('pg_proc'::regclass,l.lanplcallfoid,0)) END,'inline_handler',CASE WHEN l.laninline<>0 THEN to_jsonb(pg_identify_object('pg_proc'::regclass,l.laninline,0)) END,'validator',CASE WHEN l.lanvalidator<>0 THEN to_jsonb(pg_identify_object('pg_proc'::regclass,l.lanvalidator,0)) END) ORDER BY l.oid),'[]'::jsonb) AS payload FROM pg_language l) AS capture